import { useCallback, useEffect, useState, type FormEvent } from 'react'
import { createExpense, fetchExpenses, ValidationError, type Expense } from './api'

export function App() {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)

  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  const load = useCallback(async (signal?: AbortSignal) => {
    try {
      const list = await fetchExpenses(signal)
      setExpenses(list)
      setLoadError(null)
    } catch (e) {
      if (signal?.aborted) return
      setLoadError(e instanceof Error ? e.message : 'Failed to load expenses')
    } finally {
      if (!signal?.aborted) setLoading(false)
    }
  }, [])

  useEffect(() => {
    const controller = new AbortController()
    void load(controller.signal)
    return () => controller.abort()
  }, [load])

  async function onSubmit(e: FormEvent) {
    e.preventDefault()
    if (submitting) return
    setSubmitting(true)
    setFieldErrors({})
    setFormError(null)
    try {
      await createExpense({ label, amount: Number(amount), currency })
      setLabel('')
      setAmount('')
      await load()
    } catch (err) {
      if (err instanceof ValidationError) setFieldErrors(err.errors)
      else setFormError(err instanceof Error ? err.message : 'Failed to submit expense')
    } finally {
      setSubmitting(false)
    }
  }

  const field = (name: string, text: string, input: React.ReactNode) => (
    <div>
      <label>
        {text} {input}
      </label>
      {fieldErrors[name] && (
        <div role="alert" id={`${name}-error`}>
          {fieldErrors[name]}
        </div>
      )}
    </div>
  )

  return (
    <main>
      <h1>My expenses</h1>

      {loading && <p>Loading…</p>}
      {loadError && <p role="alert">{loadError}</p>}
      {!loading && !loadError && expenses.length === 0 && <p>No expenses yet.</p>}
      {expenses.length > 0 && (
        <table>
          <thead>
            <tr>
              <th>Label</th>
              <th>Amount</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {expenses.map((x) => (
              <tr key={x.id}>
                <td>{x.label}</td>
                <td>
                  {new Intl.NumberFormat(undefined, { style: 'currency', currency: x.currency }).format(x.amount)}
                </td>
                <td>{x.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <h2>New expense</h2>
      <form onSubmit={onSubmit} noValidate>
        {field(
          'label',
          'Label',
          <input
            name="label"
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            aria-invalid={!!fieldErrors.label}
            aria-describedby={fieldErrors.label ? 'label-error' : undefined}
          />,
        )}
        {field(
          'amount',
          'Amount',
          <input
            name="amount"
            type="number"
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            aria-invalid={!!fieldErrors.amount}
            aria-describedby={fieldErrors.amount ? 'amount-error' : undefined}
          />,
        )}
        {field(
          'currency',
          'Currency',
          <input
            name="currency"
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
            aria-invalid={!!fieldErrors.currency}
            aria-describedby={fieldErrors.currency ? 'currency-error' : undefined}
          />,
        )}
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>
    </main>
  )
}
